ALTER TABLE "users" ADD COLUMN "email_canonique" text GENERATED ALWAYS AS ((case when position('@' in lower(regexp_replace(email, '^\s+|\s+$', '', 'g'))) = 0 or substring(lower(regexp_replace(email, '^\s+|\s+$', '', 'g')) from '^(.*)@[^@]*$') = '' or substring(lower(regexp_replace(email, '^\s+|\s+$', '', 'g')) from '@([^@]*)$') = '' then lower(regexp_replace(email, '^\s+|\s+$', '', 'g'))
    when substring(lower(regexp_replace(email, '^\s+|\s+$', '', 'g')) from '@([^@]*)$') in ('gmail.com', 'googlemail.com') then coalesce(nullif(replace(regexp_replace(substring(lower(regexp_replace(email, '^\s+|\s+$', '', 'g')) from '^(.*)@[^@]*$'), '^(.[^+]*)\+.*$', '\1'), '.', ''), ''), regexp_replace(substring(lower(regexp_replace(email, '^\s+|\s+$', '', 'g')) from '^(.*)@[^@]*$'), '^(.[^+]*)\+.*$', '\1')) || '@gmail.com'
    else regexp_replace(substring(lower(regexp_replace(email, '^\s+|\s+$', '', 'g')) from '^(.*)@[^@]*$'), '^(.[^+]*)\+.*$', '\1') || '@' || substring(lower(regexp_replace(email, '^\s+|\s+$', '', 'g')) from '@([^@]*)$') end)) STORED;